text:
問題点は `var i` が関数スコープで、5つのコールバックが同じ変数 `i` を共有していることです。ループ終了後に `i` は `5` になるため、100ms 後にすべて `5` と表示されます。

修正版（`let` で各反復ごとに独立したスコープを作る）:

```js
for (let i = 0; i < 5; i++) {
  setTimeout(() => console.log(i), 100);
}
```

出力:

```text
0
1
2
3
4
```

`var` を維持したい場合は、IIFE などで値を捕捉します。

```js
for (var i = 0; i < 5; i++) {
  (function (i) {
    setTimeout(() => console.log(i), 100);
  })(i);
}
```

```go
package main

import (
	"context"
	"io"
	"net/http"
	"sync"
	"time"
)

// FetchResult は各 URL の取得結果を表します。
type FetchResult struct {
	URL        string
	StatusCode int
	Body       []byte
	Err        error
}

// FetchAll は複数の URL を並行して取得し、全体を 10 秒でタイムアウトさせます。
func FetchAll(urls []string) ([]FetchResult, error) {
	// 関数全体の期限を 10 秒に設定する。
	ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()

	client := &http.Client{}
	results := make([]FetchResult, len(urls))

	var wg sync.WaitGroup
	for i, url := range urls {
		wg.Add(1)
		go func(i int, url string) {
			defer wg.Done()

			// 各リクエストに 10 秒の期限を持つ ctx を渡す。
			req, err := http.NewRequestWithContext(ctx, http.MethodGet, url, nil)
			if err != nil {
				results[i] = FetchResult{URL: url, Err: err}
				return
			}

			resp, err := client.Do(req)
			if err != nil {
				results[i] = FetchResult{URL: url, Err: err}
				return
			}
			defer resp.Body.Close()

			body, err := io.ReadAll(resp.Body)
			results[i] = FetchResult{
				URL:        url,
				StatusCode: resp.StatusCode,
				Body:       body,
				Err:        err,
			}
		}(i, url)
	}

	// すべての取得が終わるまで待つ。
	wg.Wait()

	// 期限切れなら、そのエラーを返す。
	if err := ctx.Err(); err != nil {
		return results, err
	}

	return results, nil
}
```

呼び出し例:

```go
results, err := FetchAll([]string{
	"https://example.com",
	"https://example.org",
})
```

各 URL は独立した goroutine で並行取得され、`context.WithTimeout` により全体が 10 秒で打ち切られます。
